const input = $json;
const quotaPct = Number(input.quota_used_pct ?? input.usage_percent ?? input.quota_percent ?? 0);
const errorType = String(input.error_type ?? input.error_code ?? '').toLowerCase();
const runtimeFailure = ['quota_exceeded','rate_limit','rate_limited','timeout','provider_unavailable','billing_error'].includes(errorType) || input.provider_health === 'unhealthy';
let severity = 'INFO';
let action = 'NONE';
if (runtimeFailure || quotaPct >= 100) { severity='CRITICAL'; action='SKIP_PROVIDER_AND_ESCALATE'; }
else if (quotaPct >= 90) { severity='CRITICAL'; action='PREPARE_FALLBACK'; }
else if (quotaPct >= 80) { severity='HIGH'; action='ALERT_ADMIN'; }
else if (quotaPct >= 70) { severity='WARNING'; action='ALERT_ADMIN'; }
const dryRun = input.dry_run !== undefined ? Boolean(input.dry_run) : String($vars.SC_DRY_RUN)==='true';
return [{json:{event_id:$execution.id,environment:$vars.SC_ENVIRONMENT,project:$vars.SC_PROJECT_SLUG,timezone:$vars.SC_TIMEZONE,provider:input.provider ?? 'unknown',quota_used_pct:quotaPct,error_type:errorType||null,runtime_failure:runtimeFailure,severity,action,should_notify:severity!=='INFO',notification_mode:dryRun?'EVIDENCE_ONLY':'ADMIN_ALERT',dry_run:dryRun,schedule_interval_minutes:30,thresholds:[70,80,90,100],provider_order:['openai','claude','future_low_cost','gemini_last_resort','admin_escalation'],payload:input,observed_at:new Date().toISOString()}}];

const i = $json;
return [{ json: {
  ...i,
  alert_channel: 'LINE_ADMIN',
  alert_recipient_policy: $vars.SC_LINE_ADMIN_ROUTING || 'ADMIN_ONLY',
  alert_title: `AI Provider ${i.severity}: ${i.provider}`,
  alert_message: `Provider ${i.provider} quota ${i.quota_used_pct}% action ${i.action}`,
  escalation_status: i.dry_run ? 'EVIDENCE_ONLY' : 'READY_TO_SEND',
  evidence: {
    workflow: 'SC M4-08 AI Provider Monitoring & Admin Escalation v1.0',
    event_id: i.event_id,
    observed_at: i.observed_at,
    provider: i.provider,
    severity: i.severity,
    action: i.action
  }
} }];

const i = $json;
return [{ json: {
  ...i,
  evidence_status: i.dry_run ? 'RECORDED_DRY_RUN' : 'RECORDED_NO_ALERT',
  evidence: {
    workflow: 'SC M4-08 AI Provider Monitoring & Admin Escalation v1.0',
    event_id: i.event_id,
    observed_at: i.observed_at,
    provider: i.provider,
    quota_used_pct: i.quota_used_pct,
    severity: i.severity,
    action: i.action,
    notification_mode: i.notification_mode
  }
} }];
